function validate([n, edges, time, change]) {
  if (!Number.isInteger(n) || n < 2 || n > 10000) return 'n is between 2 and 10000.';
  if (!Array.isArray(edges) || edges.length < n - 1 || edges.length > Math.min(20000, (n * (n - 1)) / 2)) return 'edges needs between n - 1 and min(20000, n(n-1)/2) roads.';
  if (!Number.isInteger(time) || time < 1 || time > 1000) return 'time is between 1 and 1000.';
  if (!Number.isInteger(change) || change < 1 || change > 1000) return 'change is between 1 and 1000.';
  const parent = Array.from({ length: n + 1 }, (_, i) => i);
  const find = x => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each road is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 1 || v < 1 || u > n || v > n) return 'Road ends are between 1 and n.';
    if (u === v) return 'A road cannot connect an intersection to itself.';
    const key = Math.min(u, v) + ',' + Math.max(u, v);
    if (seen.has(key)) return 'Each pair of intersections has at most one road.';
    seen.add(key);
    parent[find(u)] = find(v);
  }
  for (let i = 2; i <= n; i++) if (find(i) !== find(1)) return 'The road network must be connected.';
  return null;
}

