function secondMinimum(n, edges, time, change) {
  const graph = Array.from({ length: n + 1 }, () => []);
  for (const [u, v] of edges) {
    graph[u].push(v);
    graph[v].push(u);
  }

  const first = new Array(n + 1).fill(Infinity);
  const second = new Array(n + 1).fill(Infinity);
  first[1] = 0;
  const queue = [[1, 0]];

  for (let head = 0; head < queue.length; head++) {
    const [node, steps] = queue[head];
    for (const next of graph[node]) {
      const nextSteps = steps + 1;
      if (nextSteps < first[next]) {
        first[next] = nextSteps;
        queue.push([next, nextSteps]);
      } else if (nextSteps > first[next] && nextSteps < second[next]) {
        second[next] = nextSteps;
        queue.push([next, nextSteps]);
      }
    }
  }

  let total = 0;
  for (let edge = 0; edge < second[n]; edge++) {
    const phase = Math.floor(total / change);
    if (phase % 2 === 1) {
      total = (phase + 1) * change;
    }
    total += time;
  }
  return total;
}

