function secondMinimum(n, edges, time, change) {
  const adjacent = Array.from({ length: n + 1 }, () => new Set());
  for (const [u, v] of edges) { adjacent[u].add(v); adjacent[v].add(u); }
  // Every walk of the same length takes the same time, and longer walks take longer,
  // so find the second smallest walk length that ends at n.
  let here = new Set([1]);
  const lengths = [];
  for (let length = 1; lengths.length < 2; length++) {
    const there = new Set();
    for (const node of here) for (const next of adjacent[node]) there.add(next);
    if (there.has(n)) lengths.push(length);
    here = there;
  }
  // Drive the second walk minute by minute.
  let clock = 0;
  for (let road = 0; road < lengths[1]; road++) {
    while (Math.floor(clock / change) % 2 === 1) clock++;
    clock += time;
  }
  return clock;
}

