function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 500) : 2 + Math.floor(rand() * 6);
  const reach = 1 + Math.floor(rand() * (size === 'large' ? 4 : n));
  const edges = [];
  const seen = new Set();
  const add = (u, v) => {
    const key = u < v ? u * 100000 + v : v * 100000 + u;
    if (u === v || seen.has(key)) return;
    seen.add(key);
    edges.push(rand() < 0.5 ? [u, v] : [v, u]);
  };
  // A random spanning tree keeps the graph connected; a small reach makes long paths.
  const order = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  for (let i = 1; i < n; i++) {
    const parent = order[Math.max(0, i - 1 - Math.floor(rand() * reach))];
    add(order[i], parent);
  }
  const most = Math.min(size === 'large' ? 2000 : 10, (n * (n - 1)) / 2);
  const extra = rand() < 0.5 ? Math.floor(rand() * 4) : Math.floor(rand() * (most - n + 2));
  const target = Math.min(most, n - 1 + extra);
  for (let tries = 0; edges.length < target && tries < 20 * target; tries++) {
    add(1 + Math.floor(rand() * n), 1 + Math.floor(rand() * n));
  }
  const top = size === 'large' ? 1000 : 6;
  return [n, edges, 1 + Math.floor(rand() * top), 1 + Math.floor(rand() * top)];
}
